    12	// isTerminal reports whether w is an interactive terminal. It is dependency-free
    13	// (no golang.org/x/term): a character device is a TTY, a pipe/file/bytes.Buffer
    14	// is not. Used to decide whether to draw a live progress bar and whether to
    15	// render a human summary instead of JSON.
    16	func isTerminal(w io.Writer) bool {
    17		f, ok := w.(*os.File)
    18		if !ok {
    19			return false
    20		}
    21		info, err := f.Stat()
    22		if err != nil {
    23			return false
    24		}
    25		if info.Mode()&os.ModeCharDevice == 0 {
    26			return false
    27		}
    28		// /dev/null is a character device too, so the mode bit alone would call a
    29		// redirect to it "interactive" and pick text output for a caller that asked
    30		// for none. Name-check it rather than take a terminal dependency.
    31		if name := f.Name(); name == os.DevNull {
    32			return false
    33		}
    34		return true
    35	}
